// TH18 v1.00a Extra (stage07) wave: st07.ecl.txt::MainSub01:1173-1216.
// Four groups of five Cir00; source/target correspondence is noted per block.
// Shell: validation.md control carrier (no body contact); real enemies are invulnerable.

const TIME_LIMIT: int = 1580;
const OPENING_BUFFER: int = 120;
const TH18_RICE: int = 480;

// st07.ecl.txt:31-51 Cir00_at: 16-way fixed-direction ring, type8/color2, speed 2.4.
async sub cir00_at() {
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 2);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 16, 1);
    sh_speed(0, 2.4fx, 0fx);       // etSpeed(2.4,1.0), M=1 -> s0 only
    sh_dist(0, -9.6fx);            // etEx type2/ANIM a=1: position -= 4*velocity (4*2.4)
    for i in 0..5 {                // $A=5; do { etAngle; etOn; wait(70); } while ($A--)
        sh_angle(0, (rand(65536) - 32768) as angle, 0deg); // etAngle(%RANDRAD,0)
        sh_fire(0);
        wait(70);
    }
}

// st07.ecl.txt:8-29 Cir00: hit/hurt box, then ABS polar movement.
async sub cir00() {
    set_invuln(65535);
    set_hitbox(8fx);               // setHitbox(16,16): normal circle r = 16*0.5
    set_hurtbox(14fx);             // setHurtbox(28,28): normal circle r = 28*0.5
    spawn cir00_at();              // @Cir00_at() async
    move_vel(0, 90deg, 2fx, EASE_LINEAR);              // moveVel(pi/2, 2.0)
    var u: fx = (rand(65536) - 32768) as fx / 32768;   // %RANDF2 in [-1,1)
    var off: int = (2730.6667fx * u) as int;           // RANDF2 * 0.2617994 rad (15deg)
    move_vel(120, 90deg + (off as angle), 0.5fx, EASE_LINEAR); // moveVelTime(120,0,...,0.5)
    wait(300);
    move_vel(120, 90deg, -1fx, EASE_LINEAR);           // moveVelTime(120,0,pi/2,-1.0)
    loop { wait(1000); }           // Cir00_476 wait(1000) / Cir00_496 if(1) loop
}

// st07.ecl.txt:1173-1216 MainSub01: groups start at 0/130/260/390, 14 frames apart.
async sub pattern() {
    wait(OPENING_BUFFER);
    for g in 0..4 {
        var x: fx = -160fx;
        var step: fx = 32fx;
        if g % 2 != 0 { x = 160fx; step = -32fx; }
        for i in 0..5 {
            _ = spawn_enemy(x, -32fx, 320, 0, 0, 0, cir00);
            x = x + step;
            wait(14);              // wait(14) after each enmCreate
        }
        if g < 3 { wait(60); }     // wait(60) before the next group
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
